
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_sb98_2a_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_sb98_2a", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.349375275365352e+00, -3.286813165180137e+00, -3.199168678080482e+00, -3.077808294720971e+00, -2.912562756327107e+00, -2.692954111358191e+00, -2.411147199694450e+00, -2.067427491642737e+00, -1.677848401533572e+00, -1.276636029359619e+00, -8.840455027985710e-01, -6.077564071075875e-01, -5.291298666988802e-01, -4.429966586464714e-01, -3.271435943956479e-01, -2.124384080583355e-01, -1.260971964095944e-01, -5.557897025996136e-02, -1.394067700761247e-02, -1.738651278316844e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


